public static class EvenExample {
    public static int Sum(int limit) {
        int total = 0;
        for (int i = 1; i <= limit; i++) {
            if (i % 2 != 0) continue;
            total += i;
        }
        return total;
    }
}

public static class ClampExample {
    public static int Clamp(int value, int min, int max) {
        if (min > max) throw new ArgumentException("Reversed bounds");
        return Math.Clamp(value, min, max);
    }
}

