public static class GenericExample {
    public static T First<T>(IEnumerable<T> values) {
        foreach (T value in values) return value;
        throw new InvalidOperationException("Empty sequence");
    }
}

public static class CountExample {
    public static Dictionary<string,int> Words(string text) {
        var counts = new Dictionary<string,int>(StringComparer.Ordinal);
        foreach (var word in text.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries)) {
            counts.TryGetValue(word, out int count);
            counts[word] = count + 1;
        }
        return counts;
    }
}

public static class PatternExample {
    public static string Label(object? value) => value switch {
        null => "missing",
        int n when n > 0 => "positive",
        string { Length: > 0 } => "text",
        _ => "other"
    };
}

public static class LinqExample {
    public static KeyValuePair<string,int>[] Totals(IEnumerable<OrderExample> orders) => orders
        .GroupBy(order => order.Name, StringComparer.Ordinal)
        .OrderBy(group => group.Key, StringComparer.Ordinal)
        .Select(group => new KeyValuePair<string,int>(group.Key, group.Sum(order => order.Quantity)))
        .ToArray();
}

public static class QuantityExample {
    public static int Parse(string text) {
        if (!int.TryParse(text, out int quantity) || quantity <= 0)
            throw new ArgumentException("Quantity must be a positive integer", nameof(text));
        return quantity;
    }
}

