using System.Text.Json;
public static class JsonExample {
    public static OrderExample Parse(string json) {
        var order = JsonSerializer.Deserialize<OrderExample>(json,new JsonSerializerOptions(JsonSerializerDefaults.Web));
        if (order is null || string.IsNullOrWhiteSpace(order.Name) || order.Quantity <= 0)
            throw new ArgumentException("Invalid order");
        return order;
    }
    public static string Write(OrderExample order) => JsonSerializer.Serialize(order,new JsonSerializerOptions(JsonSerializerDefaults.Web));
}

public static class HttpExample {
    public static async Task<string> FetchAsync(HttpClient client, Uri uri, CancellationToken token) {
        using var response = await client.GetAsync(uri,token);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(token);
    }
}

