using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
public static class ValidationExample {
    public static void Map(WebApplication app) {
        app.MapPost("/orders", (OrderExample order) => {
            var errors = new Dictionary<string,string[]>();
            if (string.IsNullOrWhiteSpace(order.Name)) errors["name"] = ["Name is required"];
            if (order.Quantity <= 0) errors["quantity"] = ["Quantity must be positive"];
            return errors.Count > 0 ? Results.ValidationProblem(errors) : Results.Created("/orders/1",order);
        });
    }
}

